    public var motion: String
    public var distanceM: Float?
    public var closingSpeedMS: Float?
    public var speedMS: Float?
    public var energy: UInt32?
    public var count: UInt8?
    public var id: UInt8?
    public var accelMS2: [Float]?
    public var gyroRadS: [Float]?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(kind: String, motion: String, distanceM: Float?, closingSpeedMS: Float?, speedMS: Float?, energy: UInt32?, count: UInt8?, id: UInt8?, accelMS2: [Float]?, gyroRadS: [Float]?) {
        self.kind = kind
        self.motion = motion
        self.distanceM = distanceM
        self.closingSpeedMS = closingSpeedMS
        self.speedMS = speedMS
        self.energy = energy
        self.count = count
        self.id = id
        self.accelMS2 = accelMS2
        self.gyroRadS = gyroRadS
    }
}

