extension EngineOutput: Equatable, Hashable {
    public static func ==(lhs: EngineOutput, rhs: EngineOutput) -> Bool {
        if lhs.kind != rhs.kind {
            return false
        }
        if lhs.motion != rhs.motion {
            return false
        }
        if lhs.distanceM != rhs.distanceM {
            return false
        }
        if lhs.closingSpeedMS != rhs.closingSpeedMS {
            return false
        }
        if lhs.speedMS != rhs.speedMS {
            return false
        }
        if lhs.energy != rhs.energy {
            return false
        }
        if lhs.count != rhs.count {
            return false
        }
        if lhs.id != rhs.id {
            return false
        }
        if lhs.accelMS2 != rhs.accelMS2 {
            return false
        }
        if lhs.gyroRadS != rhs.gyroRadS {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(kind)
        hasher.combine(motion)
        hasher.combine(distanceM)
        hasher.combine(closingSpeedMS)
        hasher.combine(speedMS)
        hasher.combine(energy)
        hasher.combine(count)
        hasher.combine(id)
        hasher.combine(accelMS2)
        hasher.combine(gyroRadS)
    }
}



